#!/usr/bin/env node
'use strict';

const assert = require('assert');
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const zlib = require('zlib');

const ROOT = path.resolve(__dirname, '..');

let passed = 0;
let failed = 0;
const pendingTests = [];

function _recordTestFailure(name, error) {
    failed++;
    console.error(`✗ ${name}`);
    console.error(error && error.stack ? error.stack : error);
}

function test(name, fn) {
    try {
        const result = fn();
        if (result && typeof result.then === 'function') {
            pendingTests.push(Promise.resolve(result).then(() => {
                passed++;
                console.log(`✓ ${name}`);
            }).catch(error => {
                _recordTestFailure(name, error);
            }));
            return;
        }
        passed++;
        console.log(`✓ ${name}`);
    } catch (error) {
        _recordTestFailure(name, error);
    }
}

function createContext(extra = {}) {
    const context = {
        console,
        Math,
        Set,
        Map,
        Array,
        Object,
        Number,
        String,
        Boolean,
        JSON,
        Date,
        RegExp,
        ...extra
    };
    context.window = context;
    vm.createContext(context);
    return context;
}

function loadScript(context, relativePath) {
    const filename = path.join(ROOT, relativePath);
    const code = fs.readFileSync(filename, 'utf8');
    vm.runInContext(code, context, { filename });
}

function read(relativePath) {
    return fs.readFileSync(path.join(ROOT, relativePath), 'utf8');
}

function readBinJson(relativePath) {
    return JSON.parse(zlib.inflateSync(fs.readFileSync(path.join(ROOT, relativePath))).toString('utf8'));
}

function getRuntimeData(folder = '1560_okehazama') {
    return {
        common: readBinJson('data/common.bin'),
        index: readBinJson('data/scenarios/index.bin'),
        scenario: readBinJson(`data/scenarios/${folder}/scenario.bin`)
    };
}

function mergeRuntimeRows(masterRows, stateRows) {
    const stateById = new Map(stateRows.map(row => [Number(row.id), row]));
    return masterRows.map(master => ({ ...master, ...(stateById.get(Number(master.id)) || {}) }));
}

class FakeClassList {
    constructor(initial = []) { this.values = new Set(initial); }
    add(...names) { names.forEach(name => this.values.add(name)); }
    remove(...names) { names.forEach(name => this.values.delete(name)); }
    contains(name) { return this.values.has(name); }
}

function fakeElement(id) {
    return {
        id,
        classList: new FakeClassList(),
        style: {},
        dataset: {},
        textContent: '',
        innerHTML: '',
        disabled: false,
        onclick: null,
        parentElement: null,
        querySelector() { return null; },
        querySelectorAll() { return []; },
        getAttribute() { return null; }
    };
}

// 月次ターン順はマスター行の初期位置に依存しない一様なシャッフルを使用する。
// 通常のstartMonthから対象部分を取り出し、実際のゲーム配列への作用を確認する。
test('月次ターン順はFisher–Yatesで拠点を重複なく並べ替える', () => {
    const source = read('js/turn_manager.js');
    const start = source.indexOf('const allCastles = [...game.castles];');
    const end = source.indexOf('game.updateAllClanPrestige();', start);
    assert.ok(start >= 0 && end > start, '月次ターン順の生成箇所');
    const block = source.slice(start, end);
    assert.ok(!block.includes('.sort('), '比較関数へ乱数を渡す非推移的なソートを使わない');
    const makeQueue = new Function('game', 'Math', `${block} return game.turnQueue;`);
    const originals = [1, 2, 3, 4].map(id => ({ id }));
    const game = { castles: originals };
    const values = [0, 0, 0];
    const output = makeQueue(game, { floor: Math.floor, random: () => {
        assert.ok(values.length > 0, '乱数は要素数-1回');
        return values.shift();
    }});
    assert.strictEqual(values.length, 0);
    assert.deepStrictEqual(output.map(c => c.id), [2, 3, 4, 1]);
    assert.deepStrictEqual(game.castles.map(c => c.id), [1, 2, 3, 4], 'マスター配列は書き換えない');
    assert.notStrictEqual(output, game.castles);
    assert.strictEqual(new Set(output).size, originals.length);
});

