            getRankData: id => ranks.get(Number(id)) || null,
            getHighestRankData(busho) { return (busho.courtRankIds || []).map(id => this.getRankData(id)).filter(Boolean).sort((a, b) => a.rankNo - b.rankNo)[0] || null; }
