test('新規開始とロードは実表示用地図Imageの読込・decode完了後にロード画面を閉じる', () => {
    const map = read('js/ui_map.js');
    const game = read('js/game.js');
    const save = read('js/save_manager.js');

    assert.ok(map.includes('async prepareMapBaseImage(mapW, mapH)'));
    assert.ok(map.includes("await img.decode();"), '表示用Imageは対応ブラウザでdecode完了まで待つ');
    assert.ok((map.includes("window.__mobileLowMemoryMode") && map.includes("japan_map_lowmem.png") && map.includes("japan_map_mobile.png")), '実際の端末種別に応じた表示用Imageを待つ');

    const scenarioStart = game.indexOf("this.ui.updateLoadingProgress(95, '地図を読み込んでいます')");
    const scenarioEnd = game.indexOf('// 観戦開始はロード画面を閉じてから。', scenarioStart);
    const scenarioBlock = game.slice(scenarioStart, scenarioEnd);
    assert.ok(scenarioBlock.includes('await this.ui.prepareMapBaseImage(this.mapWidth, this.mapHeight);'));
    assert.ok(scenarioBlock.indexOf('await this.ui.prepareMapBaseImage') < scenarioBlock.indexOf('this.ui.renderMap();'));
    assert.ok(scenarioBlock.indexOf('this.ui.renderMap();') < scenarioBlock.indexOf('this.ui.hideLoadingScreen();'));

    const restoreStart = save.indexOf("this.game.ui.updateLoadingProgress(95, '地図を読み込んでいます')");
    const restoreEnd = save.indexOf("window.AudioManager.playBGM", restoreStart);
    const restoreBlock = save.slice(restoreStart, restoreEnd);
    assert.ok(restoreBlock.includes('await this.game.ui.prepareMapBaseImage(this.game.mapWidth, this.game.mapHeight);'));
    assert.ok(restoreBlock.indexOf('await this.game.ui.prepareMapBaseImage') < restoreBlock.indexOf('this.game.ui.renderMap();'));
    assert.ok(restoreBlock.indexOf('this.game.ui.renderMap();') < restoreBlock.indexOf('await this.game.ui.waitForNextPaint();'));
});
test('スマホの一時資源解放では継続表示レイヤーを保持し画面復帰時に部分欠落まで検査する', () => {
    const ui = read('js/ui.js');
    const map = read('js/ui_map.js');
    const css = read('css/style.css');
    assert.ok(ui.includes('this.releaseMobileTransientMapResources()'));
    assert.ok(ui.includes('this.recoverMobileMapResources()'));
    assert.ok(ui.includes('this.recoverPersistentMapPresentation(false)'), '背景復帰の正規窓口から継続地図レイヤーを検査する');
    assert.ok(map.includes("['province-overlay', 'hover-blink-overlay', 'keep-blink-overlay']"));
    const releaseStart = map.indexOf('releaseMobileTransientMapResources()');
    const releaseEnd = map.indexOf('_getClanColorOverlayHealthProbes(', releaseStart);
    const releaseBlock = map.slice(releaseStart, releaseEnd);
    assert.ok(!releaseBlock.includes("'snow-overlay'"), '雪はAI進行やモーダル表示をまたいで保持する');
    assert.ok(map.includes('_getClanColorOverlayHealthProbes(overlay)'));
    assert.ok(map.includes('const cols = 4, rows = 4'), '勢力色の健全性確認点を地図全体へ分散する');
    assert.ok(map.includes('for (const probe of probes)'));
    assert.ok(map.includes('ctx.getImageData(probe.x, probe.y, 1, 1).data[3] <= 0'), '全Canvas readbackをせず複数の1pixelだけ確認する');
    assert.ok(map.includes('recoverPersistentMapPresentation(forceFull = false)'));
    assert.ok(map.includes('this.updateClanColors();'), '部分欠落検出時はhash無効化だけで終わらずその場で再描画する');
    assert.ok(map.includes('_refreshPersistentMapCompositeLayers()'), 'display:none/OS復帰など危険境界ではcompositor白抜けを再提示できる窓口を持つ');
    assert.ok(map.includes('this.mapEl.removeChild(layer)') && map.includes('this.mapEl.insertBefore(layer, nextSibling)'), '必要時だけ同じDOMを元位置へ付け直して巨大Canvasの全再計算を避ける');
    assert.ok(map.includes('let needsCompositeRefresh = forced || !clanHealthy;'), '通常モーダル復帰とcompositor再提示を分離する');
    assert.ok(map.includes('if (needsCompositeRefresh && this._refreshPersistentMapCompositeLayers())'), '危険境界または実Canvas欠損時だけ合成面を再提示する');
    assert.ok(map.includes('if (canReuseCastleLayer && this._mapPresentationNeedsFullRecovery)'), '同一シナリオの通常renderMapでは静的層を毎回付け直さない');
    assert.ok(!map.includes('if (canReuseCastleLayer) this._refreshPersistentMapCompositeLayers();'), '通常renderMapごとの無条件compositor再生成を残さない');
    assert.ok(ui.includes('this._schedulePersistentMapPresentationRecovery(false)'), 'モーダルが実際に閉じた次フレームでも地図表示を再確認する');
    assert.ok(ui.includes('this._mapPresentationNeedsFullRecovery = true'), 'display:noneをまたぐ経路は全復旧を予約する');
    assert.ok(map.includes("document.addEventListener('visibilitychange'"), 'OS/ブラウザ画面切替も復旧境界にする');
    assert.ok(map.includes("window.addEventListener('pageshow'"));
    assert.ok(map.includes("canvas.addEventListener('contextlost'"));
    assert.ok(css.includes('body:not(.is-pc).mobile-memory-guard .castle-card'));
});


