test('BGMはstart=0でもloopEndを適用し音量変更はcurrentBgmNameを正本にする', () => {
    class MockHowl {
        constructor(options) {
            this.options = options;
            this.bufferSource = {};
            this.lastVolume = options.volume;
            MockHowl.instances.push(this);
        }
        _soundById() { return { _node: { bufferSource: this.bufferSource } }; }
        play() { if (this.options.onplay) this.options.onplay(1); return 1; }
        stop() {}
        unload() {}
        volume(value) {
            if (value !== undefined) this.lastVolume = value;
            return this.lastVolume;
        }
    }
    MockHowl.instances = [];
    const ctx = createContext({ Howl: MockHowl });
    loadScript(ctx, 'js/audio.js');

    ctx.AudioManager.playBGM('SC_ex_Scene1_Duel.ogg');
    const duel = MockHowl.instances.at(-1);
    assert.strictEqual(duel.bufferSource.loopStart, 0);
    assert.ok(Math.abs(duel.bufferSource.loopEnd - (3841330 / 44100)) < 1e-9);

    ctx.AudioManager.playBGM('06_Snowy Sacred Approach.ogg');
    const snowy = MockHowl.instances.at(-1);
    ctx.AudioManager.setBgmVolume(0.5);
    assert.ok(Math.abs(snowy.lastVolume - 0.03) < 1e-9, 'baseVolume 0.06 を維持して音量変更する');

    const source = read('js/audio.js');
    assert.ok(!source.includes('this.bgmPlayer._src[0]'));
    assert.ok(!source.includes('if (loopStart > 0 && this.bgmPlayer)'));
});


test('旧端末安全モードBGMはAACをHTML5ストリーミングし初回intro後だけloopStartへ戻る', () => {
    class MockHowl {
        constructor(options) {
            this.options = options;
            this.playArgs = [];
            this.seekArgs = [];
            MockHowl.instances.push(this);
        }
        play(arg) { this.playArgs.push(arg); return 1; }
        seek(value, id) { this.seekArgs.push([value, id]); return this; }
        stop() {}
        unload() {}
        volume(value) { if (value !== undefined) this.lastVolume = value; return value === undefined ? this.options.volume : this; }
        mute(value) { this.lastMute = value; return this; }
    }
    MockHowl.instances = [];
    const document = {
        documentElement: { classList: new FakeClassList(['mobile-low-memory']) },
        body: { classList: new FakeClassList(['is-touch-input']) }
    };
    const ctx = createContext({ Howl: MockHowl, document, __mobileLowMemoryMode: true });
    loadScript(ctx, 'js/audio.js');

    ctx.AudioManager.playBGM('SC_ex_Town2_Fortress.ogg');
    const howl = MockHowl.instances.at(-1);
    const data = ctx.AudioManager.bgmList['SC_ex_Town2_Fortress.ogg'];
    assert.strictEqual(howl.options.html5, true);
    assert.strictEqual(howl.options.preload, 'metadata');
    assert.strictEqual(howl.options.src[0], 'data/music/bgm_mobile/SC_ex_Town2_Fortress.m4a');
    assert.strictEqual(howl.options.volume, 1, 'mobile AACへbaseVolumeを焼き込みHTML5側はユーザー音量だけを使う');
    assert.strictEqual(howl.playArgs[0], undefined, '初回は0秒から再生してintroを維持する');
    assert.strictEqual(howl.options.sprite, undefined, '初回からloopStartへ飛ぶaudio spriteは使わない');
    assert.strictEqual(typeof howl.options.onend, 'function');
    howl.options.onend(1);
    assert.ok(Math.abs(howl.seekArgs[0][0] - data.start) < 1e-12);
    assert.strictEqual(howl.seekArgs[0][1], 1);
    assert.strictEqual(howl.playArgs[1], 1, '物理終端(loopEnd)後は同じHTML5 AudioをloopStartから再開する');
    ctx.AudioManager.setBgmVolume(0.5);
    assert.strictEqual(howl.lastVolume, 0.5, 'mobile AACはbaseVolumeを二重に掛けずユーザー音量だけ反映する');
    assert.strictEqual(howl.lastMute, false);
    ctx.AudioManager.setBgmVolume(0);
    assert.strictEqual(howl.lastMute, true, 'volume固定端末でも0指定はmuteで無音にできる');

    ctx.AudioManager.playBGM('SC_ex_Town1_Castle.ogg');
    const startZero = MockHowl.instances.at(-1);
    assert.strictEqual(startZero.options.loop, true, 'loopStart=0はtrim済み音源をnative loopする');
    assert.strictEqual(startZero.options.onend, undefined);

    Object.keys(ctx.AudioManager.bgmList).forEach(fileName => {
        const mobileName = fileName.replace(/\.[^.]+$/, '') + '.m4a';
        assert.ok(fs.existsSync(path.join(ROOT, 'data/music/bgm_mobile', mobileName)), `mobile BGM missing: ${mobileName}`);
    });
});

