test('r490 ロード幕は共通レイアウト安定まで維持し、後付けモーダル・非同期部品も待つ', async () => {
    const source = read('js/ui.js');
    const start = source.indexOf('    showLoadingScreen(');
    const end = source.indexOf('    // タイトル画面の「続きから／ロード」', start);
    assert.ok(start > 0 && end > start);
    const frames = [];
    const observers = [];
    const cover = { classList: new FakeClassList(['hidden']), contains: target => target === cover };
    const modal = { width: 200, getClientRects: () => [1], getBoundingClientRect() { return { x: 1, y: 2, width: this.width, height: 120 }; } };
    const root = {
        querySelectorAll(selector) {
            if (selector === 'img[src]') return [];
            return [modal];
        }
    };
    let resolveFont;
    const fontReady = new Promise(resolve => { resolveFont = resolve; });
    const doc = { getElementById: id => id === 'game-screen' ? root : null,
        body: root, fonts: { ready: fontReady, status: 'loading' } };
    const ctx = createContext({
        document: doc, setTimeout, console,
        requestAnimationFrame: callback => { frames.push(callback); return frames.length; },
        MutationObserver: class {
            constructor(callback) { this.callback = callback; observers.push(this); }
            observe(node, options) { assert.strictEqual(node, root); assert.strictEqual(options.subtree, true); }
            disconnect() { this.disconnected = true; }
        }
    });
    vm.runInContext(`class TestLoadingUI {${source.slice(start, end)}} this.TestLoadingUI = TestLoadingUI;`, ctx);
    const ui = new ctx.TestLoadingUI();
    ui.globalLoadingScreen = cover;
    ui.showLoadingScreen('準備中', 10);
    let closed = ui.hideLoadingScreen();
    assert.strictEqual(cover.classList.contains('hidden'), false, '終了要求だけでは覆いを外さない');
    assert.strictEqual(ui.hideLoadingScreen(), closed, '同世代の二重終了をまとめる');
    await Promise.resolve();
    assert.strictEqual(frames.length, 0, 'フォント準備完了までフレーム判定を始めない');
    resolveFont(); doc.fonts.status = 'loaded';
    const tick = async () => {
        await new Promise(resolve => setImmediate(resolve));
        if (frames.length) frames.shift()(0);
        await new Promise(resolve => setImmediate(resolve));
    };
    await tick();
    assert.strictEqual(cover.classList.contains('hidden'), false);
    modal.width = 330; // 非同期でモーダルに追加された部品が幅を変える
    observers[0].callback([{ target: modal }]);
    let finishTask;
    ui.trackLoadingTask(new Promise(resolve => { finishTask = resolve; }));
    for (let i = 0; i < 6; i++) await tick();
    assert.strictEqual(cover.classList.contains('hidden'), false, '部品生成が続く間はロード幕を維持');
    finishTask();
    for (let i = 0; i < 8; i++) await tick();
    assert.strictEqual(await closed, true);
    assert.strictEqual(cover.classList.contains('hidden'), true);
    assert.strictEqual(observers[0].disconnected, true);

    // 旧画面の終了待機中に新たなロードが始まった場合は旧処理で消さない。
    ui.showLoadingScreen('旧画面', 0);
    const staleClose = ui.hideLoadingScreen();
    await tick();
    ui.showLoadingScreen('新画面', 0);
    for (let i = 0; i < 5; i++) await tick();
    assert.strictEqual(await staleClose, false);
    assert.strictEqual(cover.classList.contains('hidden'), false, '新世代の覆いを古い終了要求から守る');
    closed = ui.hideLoadingScreen();
    for (let i = 0; i < 6; i++) await tick();
    assert.strictEqual(await closed, true);
});

test('r490 ロード幕は追加された可視画像の読込完了まで閉じない', async () => {
    const source = read('js/ui.js');
    const start = source.indexOf('    showLoadingScreen(');
    const end = source.indexOf('    // タイトル画面の「続きから／ロード」', start);
    const frames = [];
    const listeners = {};
    const cover = { classList: new FakeClassList(['hidden']), contains: target => target === cover };
    const image = {
        complete: false, loading: 'eager', getClientRects: () => [1],
        addEventListener(name, fn) { listeners[name] = fn; },
        removeEventListener(name) { delete listeners[name]; }
    };
    const root = { querySelectorAll: selector => selector === 'img[src]' ? [image] : [] };
    const ctx = createContext({
        document: { getElementById: () => root, body: root, fonts: { ready: Promise.resolve(), status: 'loaded' } },
        requestAnimationFrame: fn => { frames.push(fn); },
        MutationObserver: class { constructor() {} observe() {} disconnect() {} },
        setTimeout, console
    });
    vm.runInContext(`class TestLoadingUI {${source.slice(start, end)}} this.TestLoadingUI = TestLoadingUI;`, ctx);
    const ui = new ctx.TestLoadingUI(); ui.globalLoadingScreen = cover;
    ui.showLoadingScreen();
    const done = ui.hideLoadingScreen();
    for (let i = 0; i < 5; i++) {
        await new Promise(resolve => setImmediate(resolve));
        if (frames.length) frames.shift()(0);
        await new Promise(resolve => setImmediate(resolve));
    }
    assert.strictEqual(cover.classList.contains('hidden'), false, '追加画像が読込中のまま覆いを外さない');
    assert.strictEqual(typeof listeners.load, 'function');
    image.complete = true;
    listeners.load();
    for (let i = 0; i < 7; i++) {
        await new Promise(resolve => setImmediate(resolve));
        if (frames.length) frames.shift()(0);
        await new Promise(resolve => setImmediate(resolve));
    }
    assert.strictEqual(await done, true);
});

test('r492 CSS擬似要素の城アイコンは読込とdecodeが完了するまでロード幕を維持し、後付けも監視', async () => {
    const source = read('js/ui.js');
    const start = source.indexOf('    showLoadingScreen(');
    const end = source.indexOf('    // タイトル画面の「続きから／ロード」', start);
    const frames = [];
    const observers = [];
    const requests = [];
    const cover = { classList: new FakeClassList(['hidden']), contains: target => target === cover };
    const makeCard = tier => ({ tier, getClientRects: () => [1] });
    const cards = [makeCard(1), makeCard(2)];
    const root = { querySelectorAll(selector) {
        if (selector === 'img[src]') return [];
        if (selector === '*') return cards;
        return [];
    }};
    class FakeImage {
        constructor() { this.complete = false; this.naturalWidth = 0; this.onload = null; this.onerror = null; this._resolveDecode = null; }
        set src(url) { this._src = url; requests.push(this); }
        get src() { return this._src; }
        decode() { return new Promise(resolve => { this._resolveDecode = resolve; }); }
        finishLoad() { this.complete = true; this.naturalWidth = 16; if (this.onload) this.onload(); }
        finishDecode() { if (this._resolveDecode) this._resolveDecode(); }
    }
    const ctx = createContext({
        document: { getElementById: () => root, body: root, fonts: { ready: Promise.resolve(), status: 'loaded' } },
        requestAnimationFrame: fn => { frames.push(fn); },
        MutationObserver: class { constructor(callback) { this.callback = callback; observers.push(this); } observe() {} disconnect() { this.disconnected = true; } },
        getComputedStyle: (el, pseudo) => pseudo === '::before'
            ? { content: '""', backgroundImage: `url("https://game.example/map/shiro_icon00${el.tier}.webp")` }
            : { content: 'none', backgroundImage: 'none' },
        Image: FakeImage, setTimeout, console
    });
    vm.runInContext(`class TestLoadingUI {${source.slice(start, end)}} this.TestLoadingUI = TestLoadingUI;`, ctx);
    const ui = new ctx.TestLoadingUI(); ui.globalLoadingScreen = cover;
    const tick = async () => {
        await new Promise(resolve => setImmediate(resolve));
        if (frames.length) frames.shift()(0);
        await new Promise(resolve => setImmediate(resolve));
    };
    ui.showLoadingScreen();
    const closed = ui.hideLoadingScreen();
    for (let i = 0; i < 4; i++) await tick();
    assert.strictEqual(requests.length, 2, 'CSS ::beforeの4段階画像を重複なく取得');
    assert.strictEqual(cover.classList.contains('hidden'), false, '城アイコン画像の読込前は表示しない');
    requests[0].finishLoad(); requests[1].finishLoad();
    for (let i = 0; i < 4; i++) await tick();
    assert.strictEqual(cover.classList.contains('hidden'), false, '画像のdecode完了も待機する');
    requests[0].finishDecode(); requests[1].finishDecode();
    // 待機中に子要素が増える場合、次の安定判定で新しい背景画像も捕捉する。
    cards.push(makeCard(3));
    observers[0].callback([{ target: cards[2] }]);
    for (let i = 0; i < 5; i++) await tick();
    assert.strictEqual(requests.length, 3, '追加カードの新しいCSS背景画像も自動検出');
    assert.strictEqual(cover.classList.contains('hidden'), false);
    requests[2].finishLoad();
    await tick();
    requests[2].finishDecode();
    for (let i = 0; i < 12; i++) await tick();
    assert.strictEqual(await closed, true);
    assert.strictEqual(cover.classList.contains('hidden'), true);
    assert.ok(observers[0].disconnected);
});

test('r493 通常imgのload後decodeと既読画像のdecode完了までロード幕を維持する', async () => {
    const source = read('js/ui.js');
    const start = source.indexOf('    showLoadingScreen(');
    const end = source.indexOf('    // タイトル画面の「続きから／ロード」', start);
    const frames = [];
    const cover = { classList: new FakeClassList(['hidden']), contains: target => target === cover };
    const images = [];
    const makeImg = (loaded) => {
        let resolveDecode;
        const listeners = {};
        const image = {
            src: `/assets/${images.length}.png`, currentSrc: `/assets/${images.length}.png`,
            loading: 'eager', complete: loaded, naturalWidth: loaded ? 32 : 0,
            getClientRects: () => [1],
            addEventListener(name, fn) { listeners[name] = fn; },
            removeEventListener(name) { delete listeners[name]; },
            decode() { this.decodeCount = (this.decodeCount || 0) + 1;
                return new Promise(resolve => { resolveDecode = resolve; }); },
            finishLoad() { this.complete = true; this.naturalWidth = 32;
                if (listeners.load) listeners.load(); },
            finishDecode() { if (resolveDecode) resolveDecode(); }
        };
        images.push(image);
        return image;
    };
    const loaded = makeImg(true);
    const root = { querySelectorAll(selector) { return selector === 'img[src]' ? images : []; } };
    const ctx = createContext({
        document: { getElementById: () => root, body: root, fonts: { ready: Promise.resolve(), status: 'loaded' } },
        requestAnimationFrame: fn => { frames.push(fn); },
        MutationObserver: class { constructor(cb) { this.cb = cb; } observe() {} disconnect() {} },
        setTimeout, console
    });
    vm.runInContext(`class TestLoadingUI {${source.slice(start, end)}} this.TestLoadingUI = TestLoadingUI;`, ctx);
    const ui = new ctx.TestLoadingUI(); ui.globalLoadingScreen = cover;
    const tick = async () => {
        await new Promise(resolve => setImmediate(resolve));
        if (frames.length) frames.shift()(0);
        await new Promise(resolve => setImmediate(resolve));
    };
    ui.showLoadingScreen();
    const closed = ui.hideLoadingScreen();
    for (let i = 0; i < 5; i++) await tick();
    assert.strictEqual(cover.classList.contains('hidden'), false, 'complete済みのimgもdecode待機する');
    assert.strictEqual(loaded.decodeCount, 1, '同じimgに毎フレームdecodeを要求しない');
    // decode待機中に別の画像が生成され、loadを終えてもdecode完了までは閉じない。
    const appended = makeImg(false);
    loaded.finishDecode();
    for (let i = 0; i < 4; i++) await tick();
    assert.strictEqual(cover.classList.contains('hidden'), false, '追加imgがload待ちなら幕を維持');
    appended.finishLoad();
    for (let i = 0; i < 4; i++) await tick();
    assert.strictEqual(cover.classList.contains('hidden'), false, 'load直後のdecodeも待機');
    assert.strictEqual(appended.decodeCount, 1);
    appended.finishDecode();
    for (let i = 0; i < 9; i++) await tick();
    assert.strictEqual(await closed, true);
    assert.strictEqual(cover.classList.contains('hidden'), true);
    assert.strictEqual(loaded.decodeCount, 1);
});

