// r491: スライダーの属性も表示文字列同様に入力境界で保護する。
test('r491 単体・輸送スライダーの属性は改変セーブ由来の引用符を解釈しない', () => {
    const source = read('js/ui_slider.js');
    const hostile = '500" autofocus onfocus="window.__injected=1';
    const escapePlainText = value => String(value ?? '').replace(/[&<>"']/g, ch => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    })[ch]);
    const simulate = (type) => {
        let captured = null;
        const stop = new Error('スライダー生成を確認');
        const element = () => {
            const controls = new Map();
            return {
                className: '', innerHTML: '', style: { setProperty() {} }, classList: new FakeClassList(),
                querySelector(selector) {
                    if (!controls.has(selector)) controls.set(selector, {
                        value: 0, min: '0', max: '99999', style: { setProperty() {} },
                        addEventListener() {}, classList: new FakeClassList()
                    });
                    return controls.get(selector);
                }
            };
        };
        const context = createContext({
            document: { createElement: element, getElementById: () => ({ textContent: '' }) },
            requestAnimationFrame() { return 1; },
            StatPresenter: { escapePlainText }
        });
        vm.runInContext(source, context, { filename: 'js/ui_slider.js' });
        const Slider = vm.runInContext('UISliderManager', context);
        const currentCastle = { ownerClan: 1, castellanId: 2, gold: type === 'transport' ? 500 : hostile,
            rice: 100, soldiers: 100, horses: 50, guns: 10 };
        const targetCastle = { ...currentCastle, gold: hostile };
        const ui = {
            quantityModal: element(), currentCastle,
            quantityContainer: {
                innerHTML: '', appendChild(child) {
                    if (child.className === 'qty-row') { captured = child.innerHTML; throw stop; }
                }
            },
            hideAIGuardTemporarily() {}, prepareCoveredViewForOpen() {}
        };
        const game = { getClanDaimyo: () => ({}), getBusho: () => ({}),
            getCastle: () => targetCastle };
        assert.throws(() => new Slider(ui, game).openQuantitySelector(type, [], 2), error => error === stop);
        assert.ok(captured, `${type}: スライダーの生成を確認`);
        assert.ok(!captured.includes(hostile), `${type}: 未処理の属性混入を許さない`);
        assert.ok(captured.includes('&quot;'), `${type}: 引用符は属性用にエスケープする`);
        return captured;
    };
    simulate('headhunt_gold');
    simulate('transport');
});


// r494: 保存値から到達し得る城防御値は、戦闘の通常更新・遅延更新ともHTMLへ直接入れない。
test('r494 攻城戦の城防御値は通常更新とダメージ演出更新の双方でHTMLとして解釈されない', () => {
    const context = createContext({
        setTimeout(fn, delay) { if (delay === 400) context.warDelayed = fn; return 1; },
        clearTimeout() {},
        StatPresenter: { escapePlainText(value) {
            return String(value ?? '').replace(/[&<>"']/g, ch => ({
                '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
            })[ch]);
        } }
    });
    const wall = { innerHTML: '', textContent: '120', classList: new FakeClassList() };
    const stop = new Error('通常更新の城防御描画後に停止');
    const hostile = '<img src=x onerror="window.injection=1">';
    const document = {
        getElementById(id) {
            if (id === 'war-def-wall-info') return wall;
            if (id === 'war-title-name') throw stop;
            return null;
        }
    };
    context.document = document;
    context.WarParams = { Military: { WarMaxRounds: 10 } };
    context.window.WarParams = context.WarParams;
    context.window.AudioManager = null;
    loadScript(context, 'js/ui.js');
    const UIManager = vm.runInContext('UIManager', context);
    const currentStats = { wallDefense: hostile };
    const ui = {
        game: { year: 1570, month: 2, warManager: { state: { active: true,
            round: 1, defender: { defense: hostile, isKunishu: false } } } }
    };
    assert.throws(() => UIManager.prototype.updateWarUI.call(ui), error => error === stop);
    assert.ok(!wall.innerHTML.includes(hostile), '通常更新でHTMLタグを直接挿入しない');
    assert.ok(wall.textContent === '120' || wall.innerHTML.includes('war-highlight-value'), '城防御の強調枠は維持');

    wall.innerHTML = '';
    UIManager.prototype.playDamageAnimation.call(ui, {
        type: 'damage', currentStats
    });
    assert.strictEqual(typeof context.warDelayed, 'function', '400ms後の戦況更新を確認');
    context.warDelayed();
    assert.ok(!wall.innerHTML.includes(hostile), '演出後の更新でHTMLタグを直接挿入しない');
    assert.ok(wall.innerHTML.includes('war-highlight-value'), '演出後も城防御の強調枠を維持');
    assert.ok(wall.innerHTML.includes('&lt;img'), '不正文字列はテキストとしてエスケープ');
});

