    await new Promise(resolve => setImmediate(resolve));
    generation = 2;
    game.scenarioFolder = '1570_anegawa';
    const current = saver.executeAutoSave();
    await new Promise(resolve => setImmediate(resolve));
    assert.deepStrictEqual(starts, [1], '古い書込の完了前に同スロットの新書込を開始しない');
    releaseOld();
