// r506: オートセーブは同スロットの先行書込が終わってから最新状態を一括採取する。
// 書込待機の前にスナップショットを作ると、年月と参照中の城・武将値が食い違う。
test('r506 自動保存の順番待ちでは年月と城データを同じ時点で採取する', async () => {
    const values = new Map([['autoSaveIndex', '1']]);
    const written = [];
    const ctx = createContext({
        document: {getElementById() {return null;}},
        localStorage: {
            getItem(key) {return values.get(key) ?? null;},
            setItem(key, value) {values.set(key, String(value));}
        }
    });
    loadScript(ctx, 'js/save_manager.js');
    ctx.__save = (key, data) => { written.push(JSON.parse(JSON.stringify({key, data}))); };
    vm.runInContext('saveToDB = async (key, data) => __save(key, data);', ctx);
    const game = {
        scenarioFolder: '1560_okehazama', year: 1560,
        castles: [{id: 1, gold: 100}], hasSaveData: false
    };
    const manager = new ctx.SaveManager(game);
    manager.showSaveGuard = () => {};
    manager.hideSaveGuard = () => {};
    let captureCount = 0;
    manager._createSaveDataObj = async () => {
        captureCount++;
        return {saveTimestamp: 1, year: game.year, castles: game.castles};
    };
    manager._validateSaveDataStructure = () => true;
    let releaseEarlier;
    const earlier = manager._withSerializedSlotSave('sengoku_autosave_slot1',
        () => new Promise(resolve => { releaseEarlier = resolve; }));
    const autosave = manager.executeAutoSave();
    await new Promise(resolve => setImmediate(resolve));
    assert.strictEqual(captureCount, 0, 'キュー待機中にスナップショットの参照を採らない');
    game.year = 1561;
    game.castles[0].gold = 200;
    releaseEarlier();
    await Promise.all([earlier, autosave]);
    assert.strictEqual(captureCount, 1);
    assert.strictEqual(written.length, 1);
    assert.strictEqual(written[0].data.year, 1561);
    assert.strictEqual(written[0].data.castles[0].gold, 200);
    assert.strictEqual(values.get('autoSaveIndex'), '2');
});

// r507: 正常書込／読込と非同期aborted経路でも既存のclose-once契約を保つ。
test('r507 IndexedDB正常完了・非同期中断でも接続を一度だけ閉じる', async () => {
    const ctx = createContext();
    loadScript(ctx, 'js/save_manager.js');
    const stored = new Map();
    let closeCount = 0;
    let abortNextWrite = false;
    ctx.__openDb = async () => ({
        close() { closeCount++; },
        transaction(_name, mode) {
            const tx = {
                error: null,
                objectStore() {
                    return {
                        put(data, key) {
                            Promise.resolve().then(() => {
                                if (abortNextWrite) {
                                    abortNextWrite = false;
                                    tx.error = new Error('asynchronous write abort');
                                    tx.onabort();
                                    tx.onerror(); // 両方通知されても二重closeしない
                                } else {
                                    stored.set(key, JSON.parse(JSON.stringify(data)));
                                    tx.oncomplete();
                                }
                            });
                        },
                        get(key) {
                            const request = {result: null, error: null};
                            Promise.resolve().then(() => {
                                request.result = stored.get(key);
                                request.onsuccess();
                                tx.oncomplete();
                            });
                            return request;
                        }
                    };
                }
            };
            return tx;
        }
    });
    vm.runInContext('initDB = __openDb;', ctx);
    await vm.runInContext('saveToDB("sengoku_save_slot1", {saveTimestamp: 7})', ctx);
    assert.strictEqual(closeCount, 1);
    const read = await vm.runInContext('loadFromDB("sengoku_save_slot1")', ctx);
    assert.strictEqual(read.saveTimestamp, 7);
    assert.strictEqual(closeCount, 2);
    abortNextWrite = true;
    await assert.rejects(vm.runInContext('saveToDB("sengoku_save_slot1", {saveTimestamp: 8})', ctx), /asynchronous write abort/);
    assert.strictEqual(closeCount, 3);
    assert.strictEqual(stored.get('sengoku_save_slot1').saveTimestamp, 7, '失敗した書込で保存内容を変更しない');
});

// r507: IndexedDBの同期失敗でも開いたDB接続を解放し、後続のセーブ／ロードを阻害しない。
test('r507 IndexedDBトランザクション開始・要求生成の同期例外でも接続を閉じる', async () => {
    const ctx = createContext();
    loadScript(ctx, 'js/save_manager.js');
    let closeCount = 0;
    const scenarios = [
        {name: 'transaction', failAt: 'transaction'},
        {name: 'objectStore', failAt: 'objectStore'},
        {name: 'request', failAt: 'request'}
    ];
    for (const scenario of scenarios) {
        for (const kind of ['save', 'load']) {
            let closes = 0;
            const db = {
                close() { closes++; closeCount++; },
                transaction() {
                    if (scenario.failAt === 'transaction') throw new Error('transaction failure');
                    return {
                        objectStore() {
                            if (scenario.failAt === 'objectStore') throw new Error('objectStore failure');
                            return {
                                put() { throw new Error('request failure'); },
                                get() { throw new Error('request failure'); }
                            };
                        }
                    };
                }
            };
            ctx.__openDb = async () => db;
            vm.runInContext('initDB = __openDb;', ctx);
            await assert.rejects(
                vm.runInContext(kind === 'save' ? 'saveToDB("test", {id: 1})' : 'loadFromDB("test")', ctx),
                new RegExp(`${scenario.name} failure`)
            );
            assert.strictEqual(closes, 1, `${kind}/${scenario.failAt}: DB接続は1回閉じる`);
        }
    }
    assert.strictEqual(closeCount, scenarios.length * 2);
});

// r510: 国主任命の確定までに候補・席次が変わっても、Legionと城主の正本を破壊しない。
test('r510 国主任命済み席次への遅延確定は既存国主を残し、武将も移動させない', () => {
    const ctx = createContext({ Legion: class Legion { constructor(data) { Object.assign(this, data); } },
        BushoStatusRules: { isActive: () => true } });
    loadScript(ctx, 'js/command_system.js');
    const Command = vm.runInContext('CommandSystem', ctx);
    const home = { id: 1, ownerClan: 4, legionId: 0, castellanId: 40 };
    const target = { id: 2, ownerClan: 4, legionId: 1, castellanId: 41 };
    const original = { id: 41, clan: 4, isCommander: true, isCastellan: true, castleId: 2 };
    const candidate = { id: 44, clan: 4, isCommander: false, isCastellan: false, castleId: 3 };
    const seat = { id: 8, clanId: 4, legionNo: 1, commanderId: 41, establishedTurnId: 12 };
    let moved = 0;
    let result = 0;
    const game = {
        playerClanId: 4, legions: [seat],
        getCastle: id => [home, target].find(c => Number(c.id) === Number(id)),
        getBusho: id => [original, candidate].find(b => b.id === Number(id)),
        getLegionByClanNo: (clan, no) => game.legions.find(l => l.clanId === clan && l.legionNo === no),
        getDaimyoHomeCastle: () => home,
        affiliationSystem: { moveCastle() { moved++; }, clearGunshiRole() {} },
        getCurrentTurnId: () => 25, getClan: () => ({ name: '試験家' })
    };
    game.castleManager = { getActiveCommanderCastleIds: () => new Set() }; // このテストは任命先が空城である前提
    const command = new Command(game);
    command.finishCommand = () => result++;
    command.executeAppointLegionLeader(44, 1, 2);
    assert.strictEqual(seat.commanderId, 41, '旧国主は変更されない');
    assert.strictEqual(original.isCommander, true);
    assert.strictEqual(target.castellanId, 41, '城主を置換しない');
    assert.strictEqual(target.legionId, 1);
    assert.strictEqual(candidate.isCommander, false);
    assert.strictEqual(moved, 0, '席次の競合判定より前に移動しない');
    assert.strictEqual(result, 0, '不成立を任命成功と表示しない');
});

